Here is the implementation of a recursive binary search in Python:

```python
def binary_search_recursive(arr, target, left, right):
    # Base case: if the search space is invalid, the element is not present
    if left > right:
        return -1

    # Calculate the middle index
    mid = (left + right) // 2

    # Check if the middle element is the target
    if arr[mid] == target:
        return mid
    # If the target is smaller, search in the left half
    elif arr[mid] > target:
        return binary_search_recursive(arr, target, left, mid - 1)
    # If the target is larger, search in the right half
    else:
        return binary_search_recursive(arr, target, mid + 1, right)

# Given sorted list
data = [-4, -2, 0, 6, 7, 8]

# Example usage: Search for 6
index = binary_search_recursive(data, 6, 0, len(data) - 1)

if index != -1:
    print(f"Element found at index: {index}")
else:
    print("Element not found.")
```

